int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    int copied = 0;
    int err = 0;

    if (!sk || !msg || !sock) {
        return -EINVAL;
    }

    if (len == 0) {
        return 0;
    }

    if (len > INT_MAX) {
        len = INT_MAX;
    }

    if (flags & MSG_OOB) {
        if (!sock->ops->recv_oob) {
            return -EOPNOTSUPP;
        }
        copied = sock->ops->recv_oob(sk, msg, len, flags);
        if (copied < 0) {
            return copied;
        }
        return copied;
    }

    if (sk->sk_state == TCP_LISTEN) {
        return -EOPNOTSUPP;
    }

    if (sk->sk_type == SOCK_DGRAM) {
        struct sk_buff *skb;
        skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb) {
            return -EAGAIN;
        }
        if (skb->len > len) {
            if (flags & MSG_TRUNC) {
                copied = skb->len;
            } else {
                skb_trim(skb, len);
                copied = len;
            }
        } else {
            copied = skb->len;
        }
        err = skb_copy_datagram_msg(skb, 0, msg, copied);
        if (err < 0) {
            kfree_skb(skb);
            return err;
        }
        kfree_skb(skb);
        return copied;
    }

    return -EOPNOTSUPP;
}
